        string? Message,
        bool RefreshTokenInvalid
    ) : ErrorEvent {}
    
    public record LocalAgentSettingPolicyRefused (
        LocalAgentSettingType Setting
    ) : ErrorEvent {}
    
    /// <summary>
    /// Library was unable to refresh the certificate and gave up. Client should close the connection.
    /// </summary>
